const work={"zh": [["建筑更新", "从用途与体量出发，讨论建筑节能和分期更新。", "围护结构、设备、屋顶光伏与使用管理", "实际延床面积、用电燃气、DECC 分用途强度", "业主参与、投资、施工与维护"], ["街道气候", "围绕日常步行和停留，寻找遮阴与休息条件。", "树木、遮棚、铺装、停留点与步行连续性", "现场树位、冠幅、时段、行人使用和辐射输入", "道路与沿街权属、净宽、安全和养护"], ["地区管理", "把空间措施接到可以合作的组织与行动。", "建筑组试点、共同服务与分期行动卡", "主体、权限、成本、受益人和评价口径", "企业、政府、学术界与居民的参与方式"]], "en": [["Building renewal", "Start with use and massing to discuss energy savings and phased renewal.", "Envelope, equipment, rooftop PV and operation", "Actual floor area, metered energy and DECC use-specific intensities", "Owner participation, investment, works and upkeep"], ["Street climate", "Study shade and resting conditions along everyday walking routes.", "Trees, canopies, paving, resting places and connected walks", "Tree locations, crowns, times, pedestrian use and radiation inputs", "Road and frontage rights, clear width, safety and care"], ["Area management", "Connect spatial actions with people and organisations able to deliver them.", "Building-group pilots, shared services and phased action cards", "Actors, rights, costs, beneficiaries and evaluation scope", "Participation by business, government, academia and residents"]], "ja": [["建物の更新", "用途と形態から、省エネルギーと段階的な更新を考えます。", "外皮、設備、屋根の太陽光発電、運用", "実床面積、実測使用量、DECCの用途別原単位", "所有者の参加、投資、工事、維持管理"], ["街路の気候", "日常の歩行と滞在から、日陰と休憩条件を考えます。", "樹木、庇、舗装、休憩場所、歩行の連続性", "樹木位置、樹冠、時刻、利用状況、放射の入力", "道路と沿道の権利、有効幅員、安全、管理"], ["エリアマネジメント", "空間の施策を、協力できる主体と行動につなぎます。", "建物群の試行、共同サービス、段階的な施策カード", "主体、権限、費用、受益者、評価範囲", "企業、行政、大学、住民の参加方法"]]};
let lang='en';try{lang=localStorage.getItem('kajicho-language-20261017')||'en';}catch{}if(!lex[lang])lang='en';
let study=null,loadFailed=false,boundaryData=null,plates=[];
const localized=v=>typeof v==='object'&&v!==null?(v[lang]||v.en||v.zh||''):String(v??'');
const pick=a=>a[{zh:0,en:1,ja:2}[lang]];
function link(label,href,cls='source-link'){const a=el('a',label,cls);a.href=href;if(/^https?:/.test(href)){a.target='_blank';a.rel='noopener';}return a;}
function sources(items){const box=el('div',undefined,'evidence-sources');for(const e of items||[]){const title=localized(e.document_title||e.title)||lex[lang].source;const label=[title,e.year,e.page||''].filter(Boolean).join(' · ');if(e.url)box.append(link(label+' ↗',e.url));else box.append(el('span',label));}return box;}
function openPlate(title,url){$('#dialog-title').textContent=title;$('#lightbox-image').src=url;$('#lightbox-image').alt=title;$('#lightbox-content').classList.remove('zoom');$('#zoom-map').setAttribute('aria-pressed','false');$('#map-dialog').showModal();}
function plateFigure(title,url,preview){const f=el('figure',undefined,'study-figure');const img=el('img');img.src=preview||url;img.alt=title;img.loading='lazy';img.decoding='async';f.append(img);const caption=el('figcaption');const a=link(lex[lang].downloadPNG,url);a.download='';const b=el('button',lex[lang].enlarge,'plain-action');b.addEventListener('click',()=>openPlate(title,url));caption.append(a,b);f.append(caption);return f;}
function renderContext(){const list=$('#context-list'),brief=$('#brief-checklist');if(!study){list.replaceChildren(el('p',lex[lang][loadFailed?'loadError':'loading']));return;}renderPolicyDiagrams(study,lang,{briefHost:brief,topicHost:list});}
function dataTable(headers,rows){const wrap=el('div',undefined,'table-scroll'),table=el('table'),head=el('thead'),tr=el('tr');for(const h of headers)tr.append(el('th',localized(h)));head.append(tr);table.append(head);const body=el('tbody');for(const row of rows){const r=el('tr');row.forEach((v,i)=>r.append(el(i===0?'th':'td',localized(v))));body.append(r);}table.append(body);wrap.append(table);return wrap;}
function renderEvidence(){const t=lex[lang],metrics=$('#metrics'),charts=$('#evidence-charts');metrics.replaceChildren();charts.replaceChildren();$('#seismic-risk').replaceChildren();if(!study)return;
 for(const m of study.metrics||[]){const card=el('article',undefined,'metric');card.append(el('p',localized(m.label),'reading-label'),el('b',String(m.value)+(m.unit?' '+m.unit:'')),el('p',localized(m.note)));metrics.append(card);}
 for(const [chartIndex,c] of (study.charts||[]).entries()){const article=el('article',undefined,'evidence-spread');article.id=c.id;const text=el('div',undefined,'chart-reading');text.append(el('p','DATA / '+String(chartIndex+1).padStart(2,'0'),'kicker'),el('h3',localized(c.title)),el('p',localized(c.finding),'chart-finding'));if(c.design_meaning)text.append(el('p',t.designResponse,'reading-label'),el('p',localized(c.design_meaning),'chart-meaning'));if(c.method)text.append(el('p',t.method,'reading-label'),el('p',localized(c.method),'chart-method'));if(c.limits)text.append(el('p',t.limits,'reading-label'),el('p',localized(c.limits),'chart-method'));if(c.rows?.length)text.append(dataTable(c.headers||[t.tableLabel,t.tableValue],c.rows));text.append(sources(c.sources));if(chartIndex>=5)article.append(plateFigure(localized(c.title),c.file,c.preview));else{article.classList.add('evidence-data-only');text.prepend(link(localized({en:'See the map and legend',zh:'查看地图与图例',ja:'地図と凡例を見る'}),(c.map_target==='map-00_study_area'?'#study-area':'#'+c.map_target)));}article.append(text);charts.append(article);}
 if(study.seismic?.rows?.length){const section=$('#seismic-risk');section.append(el('p','EARTHQUAKE + FIRE / 2022','kicker'),el('h3',t.seismicTitle),el('p',localized({en:'23 intersecting town units, including 15 partial census units. Published values describe the complete official towns.',zh:'相交的23个町丁目中，有15个国势调查单元仅部分位于研究区。官方风险数值对应完整町丁目。',ja:'重なる23町丁目のうち15国勢調査単位は一部のみ対象区域内。公式危険度は町丁目全体の値。'})),el('p',localized({en:'Rank 1 → 5: lower → higher relative risk. Overlap is the fraction of full 2020 census geometry; it never weights risk.',zh:'等级1→5：相对风险由低到高。相交比例按完整2020年调查几何计算，不用于加权风险。',ja:'ランク1→5：相対危険度の低→高。重なり率は2020年調査図形全体に対する比率で、危険度の重みには使わない。'}),'chart-method'));const c=study.charts.find(c=>c.presentation==='native_table'),matrix=dataTable(c.headers,c.rows);matrix.classList.add('risk-matrix');matrix.querySelectorAll('tbody tr').forEach((tr,i)=>{const row=study.seismic.rows[i];if(row.focus){tr.classList.add('risk-focus');tr.cells[0].append(el('span',localized({en:'Focus',zh:'重点',ja:'重点'}),'risk-focus-label'));}for(const index of [2,4,5]){const cell=tr.cells[index];cell.classList.add('risk-rank','rank-'+cell.textContent);}});section.append(matrix,el('p',t.seismicNote),sources(study.seismic.sources));}

}
function mapSheet(p){const layout=el('div',undefined,'map-sheet');const fig=plateFigure(localized(p.title),p.file,p.preview);const image=fig.querySelector('img');image.src=p.preview+'?v=20261018-strict-nav';if(p.preview_pixels){image.width=p.preview_pixels[0];image.height=p.preview_pixels[1];}const aside=el('aside',undefined,'map-legend');aside.setAttribute('aria-label','Legend');aside.append(el('h4',localized({en:'Legend',zh:'图例',ja:'凡例'})));const ul=el('ul');for(const entry of p.legend){const row=el('li'),swatch=el('span',undefined,'map-key '+entry.kind);swatch.style.setProperty('--key-color',entry.color);if(entry.dash)swatch.classList.add('dash');row.append(swatch,el('span',localized(entry.label)));ul.append(row);}aside.append(ul,el('p',localized(p.reading_note),'map-note'),link(localized({en:'Sources and methods',zh:'来源与方法',ja:'出典と方法'}),'study-atlas/source_manifest.json','map-source'));layout.append(fig,aside);return layout;}
function renderMaps(){const box=$('#all-maps');box.replaceChildren();plates.filter(p=>p.kind==='theme').forEach((p,i)=>{const article=el('article',undefined,'map-reading');article.id='map-'+p.id;article.append(el('p','MAP '+String(i+1).padStart(2,'0'),'kicker'),el('h3',localized(p.title)),mapSheet(p));if(p.id==='09_poi'){const insight=el('section',undefined,'poi-insights');insight.id='poi-insights';article.append(insight);box.append(article);renderPOI(insight,lang);}else box.append(article);});}
function renderBoundaries(data){const host=$('#boundary-content');host.replaceChildren(mapSheet(data.plates.find(p=>p.kind==='overview')));const primary=data.scopes.primary_brief,wider=data.scopes.study_area;host.append(dataTable([{en:'Figure 5 outline',zh:'Figure 5 边线',ja:'図5境界'},{en:'Area / ha',zh:'面积 / ha',ja:'面積 / ha'},{en:'Model objects',zh:'模型对象',ja:'モデル'}],[[{en:'Solid · primary',zh:'实线 · 重点区',ja:'実線・重点区域'},primary.area_ha.toFixed(2),primary.selected_models],[{en:'Dashed · wider (approx.)',zh:'虚线 · 外围区（概略）',ja:'破線・周辺区域（概略）'},wider.area_ha.toFixed(2),wider.selected_models]]),el('p',localized({en:'These are registered traces of the official brief. Registration RMSE: 7.43 m; screening band: 25 m. Source models stay whole; edge-sensitive membership is reported in the data.',zh:'以上为官方任务书的配准描线。配准 RMSE 7.43 m，筛查带 25 m。源模型保持完整，边缘成员敏感性在数据中报告。',ja:'公式課題書の位置合わせ済み描線。RMSE7.43m、スクリーニング帯25m。元モデルを保持し、境界付近の対応感度をデータに示す。'}),'study-boundary-note'),sources([{document_title:{en:'Official Theme B brief · Figure 5',zh:'Theme B 官方任务书 · Figure 5',ja:'Theme B公式課題書・図5'},url:'https://drive.google.com/file/d/1LkMUcYlM57gvMKpN3Hs6T2u5ykOVmIwf/view',year:'2026',page:'p.4'}]),link(localized({en:'Source trace and registration record',zh:'来源描线与配准记录',ja:'出典描線と位置合わせ記録'}),'study-atlas/study_boundary.geojson','map-source'));}

function render(){const t=lex[lang];document.documentElement.lang={zh:'zh-CN',en:'en',ja:'ja'}[lang];document.title='KAJICHO / '+t.heroTitle;document.querySelectorAll('[data-t]').forEach(n=>{if(t[n.dataset.t])n.textContent=t[n.dataset.t];});document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));renderContext();renderEvidence();renderMaps();renderSimulationPlan(lang,$("#simulation-content"));if(boundaryData)renderBoundaries(boundaryData);const lines=$('#work-lines');lines.replaceChildren();work[lang].forEach((w,i)=>{const a=el('article',undefined,'work-line');a.append(el('p','0'+(i+1),'kicker'),el('h3',w[0]),el('p',w[1]));const dl=el('dl');['action','evidence','delivery'].forEach((key,j)=>dl.append(el('dt',t[key]),el('dd',w[j+2])));a.append(dl);lines.append(a);});}
for(const b of document.querySelectorAll('[data-lang]'))b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('kajicho-language-20261017',lang);}catch{}render();});
$('#close-map').addEventListener('click',()=>$('#map-dialog').close());$('#zoom-map').addEventListener('click',()=>{const z=$('#lightbox-content').classList.toggle('zoom');$('#zoom-map').setAttribute('aria-pressed',String(z));});
$('#map-dialog').addEventListener('click',e=>{if(e.target===$('#map-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
fetch('context-study/context.json?v=20261018-brief5-poi',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Context '+r.status);return r.json();}).then(data=>{study=data;renderContext();renderEvidence();if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'instant'}));}).catch(()=>{loadFailed=true;renderContext();});



fetch("study-atlas/atlas.json?v=20261018-brief5-poi",{cache:"no-store"}).then(r=>{if(!r.ok)throw Error("Boundary atlas "+r.status);return r.json();}).then(data=>{boundaryData=data;plates=data.plates;renderMaps();renderBoundaries(data);if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'instant'}));}).catch(e=>{$("#boundary-content").append(el("p",e.message));});
